import unittest
from durations import parse_duration

class T(unittest.TestCase):
    def test_compound(self):
        self.assertEqual(parse_duration('1h30m'), 5400)
        self.assertEqual(parse_duration('1h 2m 3s'), 3723)

if __name__ == '__main__':
    unittest.main()
